-- Paket ABT "abt-alamat-putusan-28okt" (28 Okt 2026): keterangan arah di dalam KURUNG pada alamat pihak dibuang di PUTUSAN (relaas tetap utuh). 6 variabel diubah (7047, 7048, 8700, 8890, 9349, 9350), 2 fungsi paket 27 Okt diganti, 3 fungsi baru (AP).
-- Prasyarat: paket pihak-urut-ecourt-27okt dan pihak-urut-sisa-28okt sudah terpasang.
-- PRASYARAT (baca saja) "A|B|C|D|E|F|G": A = fungsi isian_rtf_pihak_identitas/utama yang isinya persis paket 27 Okt (2 pertama, 0 ulang) | B = yang sudah isi BARU paket ini (0 pertama, 2 ulang) | C = dari 6 variabel yang diubah, yang masih isi LAMA (6 pertama, 0 ulang) | D = yang sudah isi BARU (0 pertama, 6 ulang) | E = fungsi baru AP (3) yang sudah ada dengan isi persis (0 pertama, 3 ulang) | F = isian_rtf_alamat (paket alamat-ganda-26okt) yang isinya persis keadaan server (harus 1) | G = baris variabel diubah yang bukan lama bukan baru, ditambah fungsi identitas/utama yang bukan lama bukan baru (harus 0).
-- Benar: "2|0|6|0|0|1|0" (pertama) atau "0|2|0|6|3|1|0" (pasang ulang).
SELECT CONCAT((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4ee30bc89c1585852bafc1ddf67ff4c2') OR (routine_name='isian_rtf_pihak_utama' AND MD5(routine_definition)='d2fa4361de6fb016c488aad0fc8a1793'))), '|', (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4c758ce53cd541a39a32cf3cb0ba9898') OR (routine_name='isian_rtf_pihak_utama' AND MD5(routine_definition)='ecda2f98c76145e78f4b9b76ef1ceb80'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='f548b43be1206974a88aa1cd84b66822') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='485001ad3b68a7ab053d8e875ca001c4') OR (no_var=8700 AND MD5(nama)='cc04924b6d60cd2fe9d0082b9fba493a' AND data_type='data_sql' AND MD5(sql_query)='28e503d1c8a2d7ca42f4650857adb3aa') OR (no_var=8890 AND MD5(nama)='af7b94e4c0ef1b79bee1c4bba11bbe8a' AND data_type='data_sql' AND MD5(sql_query)='cc33da9647af6855dcf50700f4476a3c') OR (no_var=9349 AND MD5(nama)='a15f9d0715b5eae1e50b009c8b557575' AND data_type='data_sql' AND MD5(sql_query)='18ff1d4ac1a30da6295f73aa87dac917') OR (no_var=9350 AND MD5(nama)='40caa4ef1d8b274b9a851f0c6db9ece6' AND data_type='data_sql' AND MD5(sql_query)='e6a0c12edde5c6eb6a64511b2fba7047'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='c8fdb0dade2c0d8c7549caeabca6c08b') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='634fce56fc630914fe9446a079c9fa3a') OR (no_var=8700 AND MD5(nama)='cc04924b6d60cd2fe9d0082b9fba493a' AND data_type='data_sql' AND MD5(sql_query)='35fd01b30d22e558cba808e9b293010e') OR (no_var=8890 AND MD5(nama)='af7b94e4c0ef1b79bee1c4bba11bbe8a' AND data_type='data_sql' AND MD5(sql_query)='68d55add7505d14216829b56a0082b7d') OR (no_var=9349 AND MD5(nama)='a15f9d0715b5eae1e50b009c8b557575' AND data_type='data_sql' AND MD5(sql_query)='2d5114c2a87e34daef54c70d75028661') OR (no_var=9350 AND MD5(nama)='40caa4ef1d8b274b9a851f0c6db9ece6' AND data_type='data_sql' AND MD5(sql_query)='212cd5dd2889ef88b2c67e3aeb01f366'))), '|', (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_alamat_arah' AND MD5(routine_definition)='879b99851e6ee214706c4e5b8271a85c') OR (routine_name='isian_rtf_alamat_buang_arah' AND MD5(routine_definition)='eb549e67f9ddd4d866514c2e82ff120c') OR (routine_name='isian_rtf_alamat_putusan' AND MD5(routine_definition)='c6e37f152a9ea908a747fc59c9209034'))), '|', (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_alamat' AND MD5(routine_definition)='dfb14adb3ed8e29efaea5e2e03c6983b'), '|', ((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (7047,7048,8700,8890,9349,9350) AND NOT (((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='f548b43be1206974a88aa1cd84b66822') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='485001ad3b68a7ab053d8e875ca001c4') OR (no_var=8700 AND MD5(nama)='cc04924b6d60cd2fe9d0082b9fba493a' AND data_type='data_sql' AND MD5(sql_query)='28e503d1c8a2d7ca42f4650857adb3aa') OR (no_var=8890 AND MD5(nama)='af7b94e4c0ef1b79bee1c4bba11bbe8a' AND data_type='data_sql' AND MD5(sql_query)='cc33da9647af6855dcf50700f4476a3c') OR (no_var=9349 AND MD5(nama)='a15f9d0715b5eae1e50b009c8b557575' AND data_type='data_sql' AND MD5(sql_query)='18ff1d4ac1a30da6295f73aa87dac917') OR (no_v